FROM
data_annotation_object dao

    LEFT JOIN data_classification_option dco ON dao.data_id = dco.data_id

WHERE
dao.class_id IN

    #{classId}



    AND dao.dataset_id = #{scenarioQuery.datasetId}



    AND dao.data_id IN

        #{dataId}




    AND dco.attribute_id IN

        #{attributeId}




    AND dco.option_name IN

        #{optionName}
